// CreateSession operation middleware
func (siw *ServerInterfaceWrapper) CreateSession(c *fiber.Ctx) error {

	handler := func(c *fiber.Ctx) error {
		return siw.Handler.CreateSession(c)
	}

	for i := len(siw.HandlerMiddlewares) - 1; i >= 0; i-- {
		m := siw.HandlerMiddlewares[i]
		next := handler
		handler = func(c *fiber.Ctx) error {
			return m(c, next)
		}
	}

	return handler(c)
}

// ListChildren operation middleware
func (siw *ServerInterfaceWrapper) ListChildren(c *fiber.Ctx) error {

	var err error
	_ = err

	// Parameter object where we will unmarshal all parameters from the context
	var params ListChildrenParams

	var query url.Values
	query, err = url.ParseQuery(string(c.Request().URI().QueryString()))
	if err != nil {
		return fiber.NewError(fiber.StatusBadRequest, fmt.Errorf("Invalid format for query string: %w", err).Error())
	}

	// ------------- Optional query parameter "dn" -------------

	err = runtime.BindQueryParameterWithOptions("form", true, false, "dn", query, &params.Dn, runtime.BindQueryParameterOptions{Type: "string", Format: ""})
	if err != nil {
		return fiber.NewError(fiber.StatusBadRequest, fmt.Errorf("Invalid format for parameter dn: %w", err).Error())
	}

	// ------------- Optional query parameter "limit" -------------

	err = runtime.BindQueryParameterWithOptions("form", true, false, "limit", query, &params.Limit, runtime.BindQueryParameterOptions{Type: "integer", Format: ""})
	if err != nil {
		return fiber.NewError(fiber.StatusBadRequest, fmt.Errorf("Invalid format for parameter limit: %w", err).Error())
	}

	// ------------- Optional query parameter "cookie" -------------

	err = runtime.BindQueryParameterWithOptions("form", true, false, "cookie", query, &params.Cookie, runtime.BindQueryParameterOptions{Type: "string", Format: ""})
	if err != nil {
		return fiber.NewError(fiber.StatusBadRequest, fmt.Errorf("Invalid format for parameter cookie: %w", err).Error())
	}

	handler := func(c *fiber.Ctx) error {
		return siw.Handler.ListChildren(c, params)
	}

	for i := len(siw.HandlerMiddlewares) - 1; i >= 0; i-- {
		m := siw.HandlerMiddlewares[i]
		next := handler
		handler = func(c *fiber.Ctx) error {
			return m(c, next)
		}
	}

	return handler(c)
}

// ListObjectViews operation middleware
func (siw *ServerInterfaceWrapper) ListObjectViews(c *fiber.Ctx) error {

	handler := func(c *fiber.Ctx) error {
		return siw.Handler.ListObjectViews(c)
	}

	for i := len(siw.HandlerMiddlewares) - 1; i >= 0; i-- {
		m := siw.HandlerMiddlewares[i]
		next := handler
		handler = func(c *fiber.Ctx) error {
			return m(c, next)
		}
	}

	return handler(c)
}

// FiberServerOptions provides options for the Fiber server.
type FiberServerOptions struct {
	BaseURL            string
	Middlewares        []MiddlewareFunc
	HandlerMiddlewares []HandlerMiddlewareFunc
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router fiber.Router, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, FiberServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router fiber.Router, si ServerInterface, options FiberServerOptions) {
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.HandlerMiddlewares,
	}

	for _, m := range options.Middlewares {
		router.Use(fiber.Handler(m))
	}

	router.Delete(options.BaseURL+"/session", wrapper.DeleteSession)

	router.Get(options.BaseURL+"/session", wrapper.GetSession)

	router.Post(options.BaseURL+"/session", wrapper.CreateSession)

	router.Get(options.BaseURL+"/tree", wrapper.ListChildren)

	router.Get(options.BaseURL+"/entry", wrapper.GetEntry)

	router.Post(options.BaseURL+"/search", wrapper.Search)

	router.Get(options.BaseURL+"/views", wrapper.ListObjectViews)

	router.Get(options.BaseURL+"/schema", wrapper.GetSchema)

	router.Get(options.BaseURL+"/schema/objectclasses/:name", wrapper.GetObjectClass)

	router.Get(options.BaseURL+"/schema/attributetypes/:name", wrapper.GetAttributeType)

	router.Post(options.BaseURL+"/schema/change", wrapper.BuildSchemaChange)

	router.Post(options.BaseURL+"/changes/preview", wrapper.PreviewChange)

	router.Post(options.BaseURL+"/changes/apply", wrapper.ApplyChange)

	router.Post(options.BaseURL+"/changeset/preview", wrapper.PreviewChangeset)

	router.Post(options.BaseURL+"/changeset/apply", wrapper.ApplyChangeset)

	router.Get(options.BaseURL+"/export/ldif", wrapper.ExportLdif)

	router.Post(options.BaseURL+"/import/ldif", wrapper.ParseLdif)

}

